"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[94815],{81728:e=>{e.exports=JSON.parse('{"functions":[{"name":"solve","desc":"Twist and bend (radians) so the barrel line goes through `target`. All inputs\\nare in the waist joint frame with no bend: `muzzle`/`dir` = the barrel as it\\nsits unbent, `target` = the aim point. `pivot` (the shoulder) and `share`: the\\nwaist takes `share` of the pitch, the arms turn the rest about `pivot`. Starts\\nfrom `yaw`/`pitch`; the result is clamped to `AimPoseConfig.YawLimit` / `PitchLimit`.","params":[{"name":"muzzle","desc":"","lua_type":"Vector3"},{"name":"dir","desc":"","lua_type":"Vector3"},{"name":"target","desc":"","lua_type":"Vector3"},{"name":"yaw","desc":"","lua_type":"number"},{"name":"pitch","desc":"","lua_type":"number"},{"name":"pivot","desc":"","lua_type":"Vector3?"},{"name":"share","desc":"","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":110,"path":"src/ReplicatedStorage/SharedModules/AimPose.luau"}},{"name":"new","desc":"A pose for `rig`, or nil when it has no `UpperTorso.Waist` on its `LowerTorso`.\\nThe Waist is a Motor6D (pirate rigs: the bend goes in `C0`) or, on player\\ncharacters with upgraded avatar joints, an AnimationConstraint (the bend goes\\nin its `Attachment0.CFrame`, the same place in the joint formula:\\n`UpperTorso = Attachment0.WorldCFrame * Transform * Attachment1.CFrame:Inverse()`).\\n`LowerTorso.Root` (either kind) gives the steady frame; without it the\\nframe is the LowerTorso (sway not cancelled).","params":[{"name":"rig","desc":"","lua_type":"Model"}],"returns":[{"desc":"","lua_type":"Pose?\\n"}],"function_type":"static","source":{"line":163,"path":"src/ReplicatedStorage/SharedModules/AimPose.luau"}},{"name":"SetWeapon","desc":"Sets the held tool: its `Handle` and the Handle-space barrel direction\\n(`Tool.Grip.LookVector` for a gun; nil = aim the chest\'s forward line from\\nthe Handle, for throwables and Grabhook). nil `handle` = nothing held: the\\npose eases back to the plain animation.\\n`holdTarget` / `holdGrip`: when an IKControl pins `holdGrip` to `holdTarget`\\n(`WeaponIK`), the gun is measured where the IK puts it (the IK solves before\\nthe bend moves its target, so the hand itself is a frame late).\\n`holdIK`: that IKControl. The arms then take part of the up/down aim\\n(`1 - WaistPitchShare`): its `Offset` turns the hand about the right shoulder.","params":[{"name":"pose","desc":"","lua_type":"Pose"},{"name":"handle","desc":"","lua_type":"BasePart?"},{"name":"barrel","desc":"","lua_type":"Vector3?"},{"name":"holdTarget","desc":"","lua_type":"Attachment?"},{"name":"holdGrip","desc":"","lua_type":"Attachment?"},{"name":"holdIK","desc":"","lua_type":"IKControl?\\n"}],"returns":[],"function_type":"static","source":{"line":236,"path":"src/ReplicatedStorage/SharedModules/AimPose.luau"}},{"name":"Origin","desc":"World point the barrel line starts from (Muzzle, else Handle), or nil when nothing is held.","params":[{"name":"pose","desc":"","lua_type":"Pose"}],"returns":[{"desc":"","lua_type":"Vector3?\\n"}],"function_type":"static","source":{"line":264,"path":"src/ReplicatedStorage/SharedModules/AimPose.luau"}},{"name":"Step","desc":"One frame, after the animation step. `aimPoint` nil (or nothing held) eases\\nback to the plain animation. `rate` = follow rate (an `AimPoseConfig`\\nTurnRate). `sample` false holds the barrel sample and the waist pose (fire,\\nthrow and reload animations move the body and gun on purpose: they show).","params":[{"name":"pose","desc":"","lua_type":"Pose"},{"name":"dt","desc":"","lua_type":"number"},{"name":"aimPoint","desc":"","lua_type":"Vector3?"},{"name":"rate","desc":"","lua_type":"number"},{"name":"sample","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":311,"path":"src/ReplicatedStorage/SharedModules/AimPose.luau"}},{"name":"Destroy","desc":"Puts the waist back to its unbent joint frame.","params":[{"name":"pose","desc":"","lua_type":"Pose"}],"returns":[],"function_type":"static","source":{"line":395,"path":"src/ReplicatedStorage/SharedModules/AimPose.luau"}},{"name":"selfCheck","desc":"Pure check of `solve`: the barrel line hits the target within 0.5 degrees for an\\noffset barrel and a tilted barrel; a target behind clamps with no NaN.","params":[],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":411,"path":"src/ReplicatedStorage/SharedModules/AimPose.luau"}}],"properties":[],"types":[],"name":"AimPose","desc":"Holds an R15 rig\'s upper body steady and bends it at `UpperTorso.Waist` so\\nthe held tool\'s barrel line goes through an aim point. The legs walk; the\\ntorso, head, arms and gun are held still in the root part\'s frame (the walk\\nanimation\'s hip and waist sway is cancelled), and turn only to aim.\\nUsed on the client for player characters (`AimPoseController`) and on the\\nserver for armed pirates (`EnemyBrain`), so a pirate\'s real `Muzzle` points\\nat its target.\\n\\nThe barrel is `Handle.Muzzle` (position) plus a Handle-space direction: the\\nholding joint\'s `C1.LookVector` (`Tool.Grip` / the `EnemyGrip` weld; every\\ngun\'s barrel, by the art rule). A tool with no barrel (throwables, Grabhook)\\nuses the Handle (or its Muzzle) and the chest\'s forward line.\\n\\nNo feedback: the barrel is measured in UpperTorso space (the bend does not\\nmove it there), the twist/bend is solved in the steady frame, and the waist\\nframe is set from this frame\'s animation pose. Call `Step` after the\\nanimation step (`RunService.Stepped`), or the cancel lags a frame and the\\nbody wobbles.","source":{"line":24,"path":"src/ReplicatedStorage/SharedModules/AimPose.luau"}}')}}]);